window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-15f71db1fb196760"]={"versions": [{"id": "FIG-15f71db1fb196760", "releases": ["R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Vereinfachtes UML-Sequenzdiagramm / Interaktionsdiagramm (SOA Find-Bind-Execute-Muster).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (<code>ara::com</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Veranschaulichung des grundlegenden Service-Discovery-Musters (Broker-/Registry-basiert) zur dynamischen Kopplung zwischen Service-Providern (Skeletons) und Service-Consumern/Requestern (Proxies) zur Laufzeit vor dem direkten Datenaustausch.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Entitäten:</strong></li>\n<li><strong>Application 1 (<code>Service provider</code>):</strong> Adaptive Application in der Rolle des Dienstanbieters. Implementiert und instanziiert die typspezifische Skeleton-Klasse (<code>&lt;Service&gt;Skeleton</code>).</li>\n<li><strong>Service Registry:</strong> Logische Registry- bzw. Broker-Instanz (in POSIX/SOME/IP-Umgebungen entweder realisiert als zentraler Routing-Daemon/IPC-Broker auf Knotenebene oder über verteiltes SOME/IP-SD via Multicast über das Kommunikations-Subsystem).</li>\n<li><strong>Application 2 (<code>Service requester</code>):</strong> Adaptive Application in der Rolle des Dienstkonsumenten. Verwendet die typspezifische Proxy-Klasse (<code>&lt;Service&gt;Proxy</code>).</li>\n<li><strong>Interaktionsschnittstellen (<code>ara::com</code> API-Mapping):</strong></li>\n<li><code>offer</code>: Registrierungsschnittstelle des Providers (<code>ara::com::Skeleton::OfferService()</code>).</li>\n<li><code>find</code>: Discovery-Schnittstelle des Requesters (<code>ara::com::Proxy::FindService()</code> [synchron/Polling] oder <code>ara::com::Proxy::StartFindService()</code> [asynchron mit FindServiceHandler-Callback]).</li>\n<li><code>call</code>: Punkt-zu-Punkt-Nutzdateninteraktion (Method-Calls <code>ara::core::Future</code>, Event-Empfang oder Field-Zugriffe) direkt zwischen Requester-Proxy und Provider-Skeleton über das konfigurierte Binding (IPC oder SOME/IP).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Service Registration (<code>offer</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Aktion:</em> <code>Application 1</code> initialisiert die Service-Instanz und ruft <code>OfferService()</code> auf.</li>\n<li><em>Wirkung:</em> Ankündigung der Service-Instanz (InstanceSpecifier, Service ID, Instance ID, Major/Minor Version) an die <code>Service Registry</code> bzw. Aussenden von SOME/IP-SD Offer-Messages.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Service Resolution (<code>find</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Aktion:</em> <code>Application 2</code> sucht nach verfügbaren Instanzen (<code>FindService()</code> oder <code>StartFindService()</code>).</li>\n<li><em>Wirkung:</em> Abfrage an die <code>Service Registry</code> nach passenden Service-Deskriptoren. Bei Übereinstimmung erhält der Requester ein oder mehrere <code>ara::com::ServiceHandleType</code>-Objekte zurück, mit denen der <code>Proxy</code> konstruiert wird.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Direkte Interaktion (<code>call</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Aktion:</em> <code>Application 2</code> initiiert Methodenaufrufe oder Subscriptions direkt auf der Provider-Instanz (<code>Application 1</code>).</li>\n<li><em>Mechanik:</em> Die <code>Service Registry</code> ist nicht mehr im Nutzdatenpfad involviert; die Kommunikation erfolgt Peer-to-Peer über das konfiguriert gebundene Transportmedium (Shared Memory / Unix Domain Sockets bei lokaler IPC, Ethernet/SOME/IP bei knotenübergreifender Kommunikation).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Binding-Transparenz:</strong> Die Applikationslogik interagiert ausschließlich über die C++14/C++17 <code>ara::com</code>-Standardschnittstellen (<code>OfferService</code>, <code>FindService</code>, Service-Handle). Die physische Ausprägung der <em>Service Registry</em> (zentraler Broker vs. SOME/IP Service Discovery Multicast) wird deklarativ im ARXML-Manifest (<code>ServiceInstanceManifest</code>, Port-Interfaces, Network Binding) konfiguriert.</li>\n<li><strong>Lebenszyklus & Thread-Sicherheit:</strong></li>\n<li>Vor Zerstörung der Skeleton-Instanz <strong>muss</strong> zwingend <code>StopOfferService()</code> ausgeführt werden, um unberechtigte Aufrufe und Dead-Locks zu verhindern.</li>\n<li>Proxies müssen ungültige Service-Handles behandeln, falls der Provider terminiert oder den Dienst deregistriert.</li>\n<li><strong>Synchronisationsverhalten:</strong></li>\n<li>Synchrones <code>FindService()</code> blockiert nicht im Netzwerk, sondern liefert nur die zum Abfragezeitpunkt in der lokalen Middleware bekannten Instanzen (Snapshot-Semantik).</li>\n<li>Für asynchrone bzw. dynamisch nachstartende Provider ist zwingend <code>StartFindService()</code> mit Callback-Registrierung zu verwenden.</li>\n</ul>"}, {"id": "FIG-731aeaabf8b03532", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Vereinfachtes UML-Sequenzdiagramm / Interaktionsdiagramm (SOA Find-Bind-Execute-Muster).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (<code>ara::com</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Veranschaulichung des grundlegenden Service-Discovery-Musters (Broker-/Registry-basiert) zur dynamischen Kopplung zwischen Service-Providern (Skeletons) und Service-Consumern/Requestern (Proxies) zur Laufzeit vor dem direkten Datenaustausch.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Entitäten:</strong></li>\n<li><strong>Application 1 (<code>Service provider</code>):</strong> Adaptive Application in der Rolle des Dienstanbieters. Implementiert und instanziiert die typspezifische Skeleton-Klasse (<code>&lt;Service&gt;Skeleton</code>).</li>\n<li><strong>Service Registry:</strong> Logische Registry- bzw. Broker-Instanz (in POSIX/SOME/IP-Umgebungen entweder realisiert als zentraler Routing-Daemon/IPC-Broker auf Knotenebene oder über verteiltes SOME/IP-SD via Multicast über das Kommunikations-Subsystem).</li>\n<li><strong>Application 2 (<code>Service requester</code>):</strong> Adaptive Application in der Rolle des Dienstkonsumenten. Verwendet die typspezifische Proxy-Klasse (<code>&lt;Service&gt;Proxy</code>).</li>\n<li><strong>Interaktionsschnittstellen (<code>ara::com</code> API-Mapping):</strong></li>\n<li><code>offer</code>: Registrierungsschnittstelle des Providers (<code>ara::com::Skeleton::OfferService()</code>).</li>\n<li><code>find</code>: Discovery-Schnittstelle des Requesters (<code>ara::com::Proxy::FindService()</code> [synchron/Polling] oder <code>ara::com::Proxy::StartFindService()</code> [asynchron mit FindServiceHandler-Callback]).</li>\n<li><code>call</code>: Punkt-zu-Punkt-Nutzdateninteraktion (Method-Calls <code>ara::core::Future</code>, Event-Empfang oder Field-Zugriffe) direkt zwischen Requester-Proxy und Provider-Skeleton über das konfigurierte Binding (IPC oder SOME/IP).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Service Registration (<code>offer</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Aktion:</em> <code>Application 1</code> initialisiert die Service-Instanz und ruft <code>OfferService()</code> auf.</li>\n<li><em>Wirkung:</em> Ankündigung der Service-Instanz (InstanceSpecifier, Service ID, Instance ID, Major/Minor Version) an die <code>Service Registry</code> bzw. Aussenden von SOME/IP-SD Offer-Messages.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Service Resolution (<code>find</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Aktion:</em> <code>Application 2</code> sucht nach verfügbaren Instanzen (<code>FindService()</code> oder <code>StartFindService()</code>).</li>\n<li><em>Wirkung:</em> Abfrage an die <code>Service Registry</code> nach passenden Service-Deskriptoren. Bei Übereinstimmung erhält der Requester ein oder mehrere <code>ara::com::ServiceHandleType</code>-Objekte zurück, mit denen der <code>Proxy</code> konstruiert wird.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Direkte Interaktion (<code>call</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Aktion:</em> <code>Application 2</code> initiiert Methodenaufrufe oder Subscriptions direkt auf der Provider-Instanz (<code>Application 1</code>).</li>\n<li><em>Mechanik:</em> Die <code>Service Registry</code> ist nicht mehr im Nutzdatenpfad involviert; die Kommunikation erfolgt Peer-to-Peer über das konfiguriert gebundene Transportmedium (Shared Memory / Unix Domain Sockets bei lokaler IPC, Ethernet/SOME/IP bei knotenübergreifender Kommunikation).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Binding-Transparenz:</strong> Die Applikationslogik interagiert ausschließlich über die C++14/C++17 <code>ara::com</code>-Standardschnittstellen (<code>OfferService</code>, <code>FindService</code>, Service-Handle). Die physische Ausprägung der <em>Service Registry</em> (zentraler Broker vs. SOME/IP Service Discovery Multicast) wird deklarativ im ARXML-Manifest (<code>ServiceInstanceManifest</code>, Port-Interfaces, Network Binding) konfiguriert.</li>\n<li><strong>Lebenszyklus & Thread-Sicherheit:</strong></li>\n<li>Vor Zerstörung der Skeleton-Instanz <strong>muss</strong> zwingend <code>StopOfferService()</code> ausgeführt werden, um unberechtigte Aufrufe und Dead-Locks zu verhindern.</li>\n<li>Proxies müssen ungültige Service-Handles behandeln, falls der Provider terminiert oder den Dienst deregistriert.</li>\n<li><strong>Synchronisationsverhalten:</strong></li>\n<li>Synchrones <code>FindService()</code> blockiert nicht im Netzwerk, sondern liefert nur die zum Abfragezeitpunkt in der lokalen Middleware bekannten Instanzen (Snapshot-Semantik).</li>\n<li>Für asynchrone bzw. dynamisch nachstartende Provider ist zwingend <code>StartFindService()</code> mit Callback-Registrierung zu verwenden.</li>\n</ul>"}], "trans": [{"from": "FIG-15f71db1fb196760", "to": "FIG-731aeaabf8b03532", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
